import type { FastifyReply, FastifyRequest } from 'fastify';
import jwt from 'jsonwebtoken';
import { invalidToken, missingToken } from './errors.js';
import { prisma } from './prisma.js';

const JWT_SECRET = process.env.JWT_SECRET ?? 'realworld-dev-secret';
const JWT_EXPIRES_IN = '30d';

export interface AuthUser {
  id: number;
  username: string;
  email: string;
  bio: string | null;
  image: string | null;
}

declare module 'fastify' {
  interface FastifyRequest {
    currentUser: AuthUser | null;
  }
}

export function signToken(user: { id: number; username: string }): string {
  return jwt.sign({ id: user.id, username: user.username }, JWT_SECRET, {
    expiresIn: JWT_EXPIRES_IN,
  });
}

/**
 * The RealWorld spec uses the `Token <jwt>` scheme; `Bearer` is accepted as a
 * convenience since several official frontends send it.
 */
function extractToken(header: string | undefined): string | null {
  if (!header) return null;
  const match = /^(Token|Bearer)\s+(.+)$/i.exec(header.trim());
  return match ? match[2].trim() : null;
}

async function resolveUser(request: FastifyRequest): Promise<AuthUser | null> {
  const token = extractToken(request.headers.authorization);
  if (!token) return null;

  let payload: jwt.JwtPayload;
  try {
    payload = jwt.verify(token, JWT_SECRET) as jwt.JwtPayload;
  } catch {
    throw invalidToken();
  }

  const user = await prisma.user.findUnique({ where: { id: Number(payload.id) } });
  if (!user) throw invalidToken();

  return { id: user.id, username: user.username, email: user.email, bio: user.bio, image: user.image };
}

/** Populates `request.currentUser` when a token is present; never rejects a missing token. */
export async function optionalAuth(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
  request.currentUser = await resolveUser(request);
}

/** Populates `request.currentUser` and rejects requests without a valid token. */
export async function requireAuth(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
  if (!extractToken(request.headers.authorization)) throw missingToken();
  request.currentUser = await resolveUser(request);
}

/** Narrowing helper for handlers registered behind `requireAuth`. */
export function currentUser(request: FastifyRequest): AuthUser {
  if (!request.currentUser) throw missingToken();
  return request.currentUser;
}

