import { unprocessable } from './errors.js';

export type JsonObject = Record<string, unknown>;

const isPlainObject = (value: unknown): value is JsonObject =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/**
 * Every RealWorld payload is namespaced (`{ "user": {...} }`, `{ "article": {...} }`).
 * A missing or malformed envelope is reported against the namespace itself.
 */
export function envelope(body: unknown, key: string): JsonObject {
  if (!isPlainObject(body) || !isPlainObject(body[key])) {
    throw unprocessable(key, "can't be blank");
  }
  return body[key];
}

export const has = (payload: JsonObject, field: string): boolean =>
  Object.prototype.hasOwnProperty.call(payload, field);

/** Required non-blank string, e.g. an article title on create. */
export function requiredString(payload: JsonObject, field: string): string {
  const value = payload[field];
  if (typeof value !== 'string' || value.trim() === '') {
    throw unprocessable(field);
  }
  return value;
}

/** Optional non-blank string: absent keeps the current value, blank/null is rejected. */
export function optionalString(payload: JsonObject, field: string): string | undefined {
  if (!has(payload, field)) return undefined;
  return requiredString(payload, field);
}

/**
 * Optional nullable string (`bio`, `image`): absent keeps the current value,
 * while `null` and `""` both normalize to `null`.
 */
export function optionalNullableString(
  payload: JsonObject,
  field: string,
): string | null | undefined {
  if (!has(payload, field)) return undefined;

  const value = payload[field];
  if (value === null || value === '') return null;
  if (typeof value !== 'string') throw unprocessable(field, 'is invalid');
  return value;
}

/** NIST SP 800-63B: at least 8 characters, at least 64 accepted, no composition rules. */
export const PASSWORD_MIN_LENGTH = 8;
export const PASSWORD_MAX_LENGTH = 128;

export function validatePassword(value: unknown, { requireMinLength = true } = {}): string {
  if (typeof value !== 'string' || value === '') {
    throw unprocessable('password');
  }
  if (requireMinLength && value.length < PASSWORD_MIN_LENGTH) {
    throw unprocessable('password', `is too short (minimum is ${PASSWORD_MIN_LENGTH} characters)`);
  }
  if (value.length > PASSWORD_MAX_LENGTH) {
    throw unprocessable('password', `is too long (maximum is ${PASSWORD_MAX_LENGTH} characters)`);
  }
  return value;
}

/** Optional tag list: absent keeps the current tags, `[]` clears them, `null` is rejected. */
export function optionalTagList(payload: JsonObject): string[] | undefined {
  if (!has(payload, 'tagList')) return undefined;

  const value = payload.tagList;
  if (!Array.isArray(value)) throw unprocessable('tagList', 'is invalid');

  const tags = value.map((tag) => {
    if (typeof tag !== 'string' || tag.trim() === '') throw unprocessable('tagList', 'is invalid');
    return tag.trim();
  });

  return [...new Set(tags)];
}

/** Clamped, non-negative integer query parameter. */
export function positiveInt(value: unknown, fallback: number, max = 1000): number {
  if (value === undefined || value === null || value === '') return fallback;
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) return fallback;
  return Math.min(Math.floor(parsed), max);
}

