  createdAt: string;
  updatedAt: string;
  favorited: boolean;
  favoritesCount: number;
  author: ProfileJSON;
}

export type ArticleWithRelations = Article & {
  author: User;
  tags: (ArticleTag & { tag: Tag })[];
  _count: { favorites: number };
};

export type CommentWithAuthor = Comment & { author: User };

export const toUserJSON = (user: User, token: string) => ({
  user: {
    email: user.email,
    token,
    username: user.username,
    bio: user.bio,
    image: user.image,
  },
});

export const toProfileJSON = (user: User, following: boolean): { profile: ProfileJSON } => ({
  profile: {
    username: user.username,
    bio: user.bio,
    image: user.image,
    following,
  },
});

export function toArticleJSON(
  article: ArticleWithRelations,
  options: { favorited: boolean; following: boolean; includeBody?: boolean },
): ArticleJSON {
  const json: ArticleJSON = {
    slug: article.slug,
    title: article.title,
    description: article.description,
    tagList: article.tags.map((link) => link.tag.name).sort(),
    createdAt: article.createdAt.toISOString(),
    updatedAt: article.updatedAt.toISOString(),
    favorited: options.favorited,
    favoritesCount: article._count.favorites,
    author: toProfileJSON(article.author, options.following).profile,
  };

  // List endpoints deliberately omit `body`.
  if (options.includeBody !== false) json.body = article.body;

  return json;
}

export const toCommentJSON = (comment: CommentWithAuthor, following: boolean) => ({
  id: comment.id,
  createdAt: comment.createdAt.toISOString(),
  updatedAt: comment.updatedAt.toISOString(),
  body: comment.body,
  author: toProfileJSON(comment.author, following).profile,
});

