import type { Prisma } from '@prisma/client';
import { prisma } from './prisma.js';
import { toArticleJSON, type ArticleJSON, type ArticleWithRelations } from './presenters.js';

export const articleInclude = {
  author: true,
  tags: { include: { tag: true } },
  _count: { select: { favorites: true } },
} satisfies Prisma.ArticleInclude;

/** Newest first; the id breaks ties when two articles share a timestamp. */
export const articleOrderBy: Prisma.ArticleOrderByWithRelationInput[] = [
  { createdAt: 'desc' },
  { id: 'desc' },
];

export function slugify(title: string): string {
  const base = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return base || 'article';
}

/** Duplicate titles are allowed, so the slug gets a numeric suffix until it is free. */
export async function uniqueSlug(title: string, excludeArticleId?: number): Promise<string> {
  const base = slugify(title);
  for (let attempt = 0; ; attempt += 1) {
    const candidate = attempt === 0 ? base : `${base}-${attempt + 1}`;
    const existing = await prisma.article.findUnique({ where: { slug: candidate } });
    if (!existing || existing.id === excludeArticleId) return candidate;
  }
}

/** Creates any missing tags and returns their ids, preserving the requested order. */
export async function upsertTags(names: string[]): Promise<number[]> {
  const ids: number[] = [];
  for (const name of names) {
    const tag = await prisma.tag.upsert({
      where: { name },
      update: {},
      create: { name },
    });
    ids.push(tag.id);
  }
  return ids;
}

async function followedAuthorIds(
  currentUserId: number | null,
  authorIds: number[],
): Promise<Set<number>> {
  if (currentUserId === null || authorIds.length === 0) return new Set();
  const follows = await prisma.follow.findMany({
    where: { followerId: currentUserId, followeeId: { in: authorIds } },
    select: { followeeId: true },
  });
  return new Set(follows.map((follow) => follow.followeeId));
}

async function favoritedArticleIds(
  currentUserId: number | null,
  articleIds: number[],
): Promise<Set<number>> {
  if (currentUserId === null || articleIds.length === 0) return new Set();
  const favorites = await prisma.favorite.findMany({
    where: { userId: currentUserId, articleId: { in: articleIds } },
    select: { articleId: true },
  });
  return new Set(favorites.map((favorite) => favorite.articleId));
}

export async function presentArticles(
  articles: ArticleWithRelations[],
  currentUserId: number | null,
  { includeBody = true } = {},
): Promise<ArticleJSON[]> {
  const [following, favorited] = await Promise.all([
    followedAuthorIds(currentUserId, articles.map((article) => article.authorId)),
    favoritedArticleIds(currentUserId, articles.map((article) => article.id)),
  ]);

  return articles.map((article) =>
    toArticleJSON(article, {
      favorited: favorited.has(article.id),
      following: following.has(article.authorId),
      includeBody,
    }),
  );
}

export async function presentArticle(
  article: ArticleWithRelations,
  currentUserId: number | null,
): Promise<ArticleJSON> {
  const [json] = await presentArticles([article], currentUserId);
  return json;
}

/** Reloads an article with every relation the presenters need. */
export async function loadArticle(id: number): Promise<ArticleWithRelations> {
  return prisma.article.findUniqueOrThrow({ where: { id }, include: articleInclude });
}

export async function isFollowing(
  currentUserId: number | null,
  targetUserId: number,
): Promise<boolean> {
  if (currentUserId === null) return false;
  const follow = await prisma.follow.findUnique({
    where: { followerId_followeeId: { followerId: currentUserId, followeeId: targetUserId } },
  });
  return follow !== null;
}

