import type { FastifyInstance } from 'fastify';
import { currentUser, optionalAuth, requireAuth, signToken } from '../auth.js';
import { conflict, invalidCredentials, unprocessable } from '../errors.js';
import { hashPassword, verifyPassword } from '../password.js';
import { toUserJSON } from '../presenters.js';
import { prisma } from '../prisma.js';
import {
  envelope,
  has,
  optionalNullableString,
  requiredString,
  validatePassword,
} from '../validation.js';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validateEmail(value: string): string {
  if (!EMAIL_PATTERN.test(value)) throw unprocessable('email', 'is invalid');
  return value;
}

async function assertUsernameAvailable(username: string, excludeUserId?: number): Promise<void> {
  const existing = await prisma.user.findUnique({ where: { username } });
  if (existing && existing.id !== excludeUserId) throw conflict('username');
}

async function assertEmailAvailable(email: string, excludeUserId?: number): Promise<void> {
  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing && existing.id !== excludeUserId) throw conflict('email');
}

export default async function userRoutes(app: FastifyInstance): Promise<void> {
  // Registration
  app.post('/api/users', async (request, reply) => {
    const payload = envelope(request.body, 'user');

    const username = requiredString(payload, 'username');
    const email = validateEmail(requiredString(payload, 'email'));
    const password = validatePassword(payload.password);

    await assertUsernameAvailable(username);
    await assertEmailAvailable(email);

    const user = await prisma.user.create({
      data: { username, email, passwordHash: await hashPassword(password) },
    });

    return reply.code(201).send(toUserJSON(user, signToken(user)));
  });

  // Login
  app.post('/api/users/login', async (request, reply) => {
    const payload = envelope(request.body, 'user');

    const email = requiredString(payload, 'email');
    // Login must not enforce the registration password policy, only presence.
    const password = validatePassword(payload.password, { requireMinLength: false });

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !(await verifyPassword(password, user.passwordHash))) {
      throw invalidCredentials();
    }

    return reply.code(200).send(toUserJSON(user, signToken(user)));
  });

  // Current user
  app.get('/api/user', { preHandler: requireAuth }, async (request, reply) => {
    const auth = currentUser(request);
    const user = await prisma.user.findUniqueOrThrow({ where: { id: auth.id } });
    return reply.code(200).send(toUserJSON(user, signToken(user)));
  });

  // Update current user
  app.put('/api/user', { preHandler: requireAuth }, async (request, reply) => {
    const auth = currentUser(request);
    const payload = envelope(request.body, 'user');

    const data: {
      username?: string;
      email?: string;
      passwordHash?: string;
      bio?: string | null;
      image?: string | null;
    } = {};

    if (has(payload, 'username')) {
      const username = requiredString(payload, 'username');
      await assertUsernameAvailable(username, auth.id);
      data.username = username;
    }

    if (has(payload, 'email')) {
      const email = validateEmail(requiredString(payload, 'email'));
      await assertEmailAvailable(email, auth.id);
      data.email = email;
    }

    if (has(payload, 'password')) {
      data.passwordHash = await hashPassword(validatePassword(payload.password));
    }

    const bio = optionalNullableString(payload, 'bio');
    if (bio !== undefined) data.bio = bio;

    const image = optionalNullableString(payload, 'image');
    if (image !== undefined) data.image = image;

    const user = await prisma.user.update({
      where: { id: auth.id },
      data: { ...data, updatedAt: new Date() },
    });

    return reply.code(200).send(toUserJSON(user, signToken(user)));
  });

  // Not part of the spec, but handy for readiness checks.
  app.get('/api/health', { preHandler: optionalAuth }, async (_request, reply) =>
    reply.code(200).send({ status: 'ok' }),
  );
}

