import type { FastifyInstance } from 'fastify';
import { isFollowing } from '../article-service.js';
import { currentUser, optionalAuth, requireAuth } from '../auth.js';
import { notFound } from '../errors.js';
import { toProfileJSON } from '../presenters.js';
import { prisma } from '../prisma.js';

interface UsernameParams {
  username: string;
}

async function findProfile(username: string) {
  const user = await prisma.user.findUnique({ where: { username } });
  if (!user) throw notFound('profile');
  return user;
}

export default async function profileRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Params: UsernameParams }>(
    '/api/profiles/:username',
    { preHandler: optionalAuth },
    async (request, reply) => {
      const target = await findProfile(request.params.username);
      const following = await isFollowing(request.currentUser?.id ?? null, target.id);
      return reply.code(200).send(toProfileJSON(target, following));
    },
  );

  app.post<{ Params: UsernameParams }>(
    '/api/profiles/:username/follow',
    { preHandler: requireAuth },
    async (request, reply) => {
      const auth = currentUser(request);
      const target = await findProfile(request.params.username);

      if (target.id !== auth.id) {
        await prisma.follow.upsert({
          where: { followerId_followeeId: { followerId: auth.id, followeeId: target.id } },
          update: {},
          create: { followerId: auth.id, followeeId: target.id },
        });
      }

      return reply.code(200).send(toProfileJSON(target, target.id !== auth.id));
    },
  );

  app.delete<{ Params: UsernameParams }>(
    '/api/profiles/:username/follow',
    { preHandler: requireAuth },
    async (request, reply) => {
      const auth = currentUser(request);
      const target = await findProfile(request.params.username);

      await prisma.follow.deleteMany({ where: { followerId: auth.id, followeeId: target.id } });

      return reply.code(200).send(toProfileJSON(target, false));
    },
  );
}

