import type { Prisma } from '@prisma/client';
import type { FastifyInstance } from 'fastify';
import {
  articleInclude,
  articleOrderBy,
  loadArticle,
  presentArticle,
  presentArticles,
  uniqueSlug,
  upsertTags,
} from '../article-service.js';
import { currentUser, optionalAuth, requireAuth } from '../auth.js';
import { forbidden, notFound } from '../errors.js';
import { prisma } from '../prisma.js';
import {
  envelope,
  has,
  optionalString,
  optionalTagList,
  positiveInt,
  requiredString,
} from '../validation.js';

interface SlugParams {
  slug: string;
}

interface ListQuery {
  tag?: string;
  author?: string;
  favorited?: string;
  limit?: string;
  offset?: string;
}

async function findArticleBySlug(slug: string) {
  const article = await prisma.article.findUnique({ where: { slug }, include: articleInclude });
  if (!article) throw notFound('article');
  return article;
}

/** Guarantees a strictly newer `updatedAt` even when two writes land in the same millisecond. */
const bumpedTimestamp = (previous: Date): Date => {
  const now = new Date();
  return now.getTime() > previous.getTime() ? now : new Date(previous.getTime() + 1);
};

async function replaceTags(articleId: number, tagList: string[]): Promise<void> {
  const tagIds = await upsertTags(tagList);
  await prisma.articleTag.deleteMany({
    where: { articleId, tagId: { notIn: tagIds.length > 0 ? tagIds : [-1] } },
  });
  for (const tagId of tagIds) {
    await prisma.articleTag.upsert({
      where: { articleId_tagId: { articleId, tagId } },
      update: {},
      create: { articleId, tagId },
    });
  }
}

export default async function articleRoutes(app: FastifyInstance): Promise<void> {
  // List articles
  app.get<{ Querystring: ListQuery }>(
    '/api/articles',
    { preHandler: optionalAuth },
    async (request, reply) => {
      const { tag, author, favorited } = request.query;
      const limit = positiveInt(request.query.limit, 20);
      const offset = positiveInt(request.query.offset, 0);

      const where: Prisma.ArticleWhereInput = {};
      if (tag) where.tags = { some: { tag: { name: tag } } };
      if (author) where.author = { username: author };
      if (favorited) where.favorites = { some: { user: { username: favorited } } };

      const [articles, articlesCount] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude,
          orderBy: articleOrderBy,
          take: limit,
          skip: offset,
        }),
        prisma.article.count({ where }),
      ]);

      const payload = await presentArticles(articles, request.currentUser?.id ?? null, {
        includeBody: false,
      });
      return reply.code(200).send({ articles: payload, articlesCount });
    },
  );

  // Feed of followed authors
  app.get<{ Querystring: ListQuery }>(
    '/api/articles/feed',
    { preHandler: requireAuth },
    async (request, reply) => {
