    const body = requiredString(payload, 'body');
    const tagList = optionalTagList(payload) ?? [];

    const created = await prisma.article.create({
      data: {
        slug: await uniqueSlug(title),
        title,
        description,
        body,
        authorId: auth.id,
      },
    });

    if (tagList.length > 0) await replaceTags(created.id, tagList);

    const article = await loadArticle(created.id);
    return reply.code(201).send({ article: await presentArticle(article, auth.id) });
  });

  // Update article
  app.put<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (request, reply) => {
      const auth = currentUser(request);
      const existing = await findArticleBySlug(request.params.slug);
      if (existing.authorId !== auth.id) throw forbidden('article');

      const payload = envelope(request.body, 'article');
      const title = optionalString(payload, 'title');
      const description = optionalString(payload, 'description');
      const body = optionalString(payload, 'body');
      const tagList = optionalTagList(payload);

      const data: Prisma.ArticleUpdateInput = { updatedAt: bumpedTimestamp(existing.updatedAt) };
      if (title !== undefined && title !== existing.title) {
        data.title = title;
        data.slug = await uniqueSlug(title, existing.id);
      }
      if (description !== undefined) data.description = description;
      if (body !== undefined) data.body = body;

      await prisma.article.update({ where: { id: existing.id }, data });
      if (tagList !== undefined) await replaceTags(existing.id, tagList);

      const article = await loadArticle(existing.id);
      return reply.code(200).send({ article: await presentArticle(article, auth.id) });
    },
  );

  // Delete article
  app.delete<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (request, reply) => {
      const auth = currentUser(request);
      const existing = await findArticleBySlug(request.params.slug);
      if (existing.authorId !== auth.id) throw forbidden('article');

      await prisma.article.delete({ where: { id: existing.id } });
      return reply.code(204).send();
    },
  );

  // Favorite article
  app.post<{ Params: SlugParams }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request, reply) => {
      const auth = currentUser(request);
      const existing = await findArticleBySlug(request.params.slug);

      await prisma.favorite.upsert({
        where: { userId_articleId: { userId: auth.id, articleId: existing.id } },
        update: {},
        create: { userId: auth.id, articleId: existing.id },
      });

      const article = await loadArticle(existing.id);
      return reply.code(200).send({ article: await presentArticle(article, auth.id) });
    },
  );

  // Unfavorite article
  app.delete<{ Params: SlugParams }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request, reply) => {
      const auth = currentUser(request);
      const existing = await findArticleBySlug(request.params.slug);

      await prisma.favorite.deleteMany({ where: { userId: auth.id, articleId: existing.id } });

      const article = await loadArticle(existing.id);
      return reply.code(200).send({ article: await presentArticle(article, auth.id) });
    },
  );

  // `has` is re-exported implicitly by validation; referenced here to keep imports honest.
  void has;
}

