import type { FastifyInstance } from 'fastify';
import { articleInclude } from '../article-service.js';
import { currentUser, optionalAuth, requireAuth } from '../auth.js';
import { forbidden, notFound } from '../errors.js';
import { toCommentJSON, type CommentWithAuthor } from '../presenters.js';
import { prisma } from '../prisma.js';
import { envelope, requiredString } from '../validation.js';

interface SlugParams {
  slug: string;
}

interface CommentParams extends SlugParams {
  id: string;
}

async function findArticleBySlug(slug: string) {
  const article = await prisma.article.findUnique({ where: { slug }, include: articleInclude });
  if (!article) throw notFound('article');
  return article;
}

/** Resolves the `following` flag for every distinct comment author in one query. */
async function presentComments(comments: CommentWithAuthor[], currentUserId: number | null) {
  const authorIds = [...new Set(comments.map((comment) => comment.authorId))];

  let following = new Set<number>();
  if (currentUserId !== null && authorIds.length > 0) {
    const follows = await prisma.follow.findMany({
      where: { followerId: currentUserId, followeeId: { in: authorIds } },
      select: { followeeId: true },
    });
    following = new Set(follows.map((follow) => follow.followeeId));
  }

  return comments.map((comment) => toCommentJSON(comment, following.has(comment.authorId)));
}

export default async function commentRoutes(app: FastifyInstance): Promise<void> {
  // Add a comment
  app.post<{ Params: SlugParams }>(
    '/api/articles/:slug/comments',
    { preHandler: requireAuth },
    async (request, reply) => {
      const auth = currentUser(request);
      const article = await findArticleBySlug(request.params.slug);

      const payload = envelope(request.body, 'comment');
      const body = requiredString(payload, 'body');

      const created = await prisma.comment.create({
        data: { body, articleId: article.id, authorId: auth.id },
        include: { author: true },
      });

      const [comment] = await presentComments([created], auth.id);
      return reply.code(201).send({ comment });
    },
  );

  // List comments
  app.get<{ Params: SlugParams }>(
    '/api/articles/:slug/comments',
    { preHandler: optionalAuth },
    async (request, reply) => {
      const article = await findArticleBySlug(request.params.slug);

      const comments = await prisma.comment.findMany({
        where: { articleId: article.id },
        include: { author: true },
        orderBy: [{ createdAt: 'asc' }, { id: 'asc' }],
      });

      const payload = await presentComments(comments, request.currentUser?.id ?? null);
      return reply.code(200).send({ comments: payload });
    },
  );

  // Delete a comment
  app.delete<{ Params: CommentParams }>(
    '/api/articles/:slug/comments/:id',
    { preHandler: requireAuth },
    async (request, reply) => {
      const auth = currentUser(request);
      const article = await findArticleBySlug(request.params.slug);

      const commentId = Number(request.params.id);
      if (!Number.isInteger(commentId)) throw notFound('comment');

      const comment = await prisma.comment.findFirst({
        where: { id: commentId, articleId: article.id },
      });
      if (!comment) throw notFound('comment');
      if (comment.authorId !== auth.id) throw forbidden('comment');

      await prisma.comment.delete({ where: { id: comment.id } });
      return reply.code(204).send();
    },
  );
}

