import { Prisma } from '@prisma/client';
import Fastify, { type FastifyInstance } from 'fastify';
import { ApiError } from './errors.js';
import articleRoutes from './routes/articles.js';
import commentRoutes from './routes/comments.js';
import profileRoutes from './routes/profiles.js';
import tagRoutes from './routes/tags.js';
import userRoutes from './routes/users.js';

export function buildApp(options: { logger?: boolean } = {}): FastifyInstance {
  const app = Fastify({ logger: options.logger ?? false });

  app.decorateRequest('currentUser', null);

  // Treat an empty JSON body as `{}` so bodyless POST/DELETE routes work unchanged.
  app.addContentTypeParser(
    'application/json',
    { parseAs: 'string' },
    (_request, body: string, done) => {
      if (body === '') return done(null, {});
      try {
        done(null, JSON.parse(body));
      } catch {
        done(new ApiError(422, { body: ['is invalid'] }), undefined);
      }
    },
  );

  app.setNotFoundHandler((_request, reply) =>
    reply.code(404).send({ errors: { route: ['not found'] } }),
  );

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof ApiError) {
      return reply.code(error.statusCode).send({ errors: error.errors });
    }

    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      // P2002: unique constraint, P2025: record required but not found.
      if (error.code === 'P2002') {
        const target = error.meta?.target;
        const field = Array.isArray(target) ? String(target[0]) : 'record';
        return reply.code(409).send({ errors: { [field]: ['has already been taken'] } });
      }
      if (error.code === 'P2025') {
        return reply.code(404).send({ errors: { record: ['not found'] } });
      }
    }

    const statusCode = error.statusCode ?? 500;
    if (statusCode >= 500) {
      app.log.error(error);
      return reply.code(500).send({ errors: { server: ['internal error'] } });
    }

    return reply.code(statusCode).send({ errors: { request: [error.message] } });
  });

  app.register(userRoutes);
  app.register(profileRoutes);
  app.register(articleRoutes);
  app.register(commentRoutes);
  app.register(tagRoutes);

  return app;
}

